        for line in open(f,encoding='utf-8',errors='ignore'):
            if 'Skill' not in line and 'command-name' not in line: continue
            names=[m.group(1) for m in re.finditer(r'"name"\s*:\s*"Skill"\s*,\s*"input"\s*:\s*\{[^}]*?"skill"\s*:\s*"([^"]+)"', line)]
            names+=[m.group(1) for m in re.finditer(r'<command-name>/([a-zA-Z0-9:_-]+)</command-name>', line)]
            for n in names:
                c[n]+=1; last[n]=max(last.get(n,0),mt)
    except Exception: pass
print("sessions:",len(files))
for k,v in sorted(c.items(),key=lambda x:-x[1]):
    print(f"{v:5d}  {datetime.date.fromtimestamp(last[k])}  {k}")
EOF
